:root {
  --bg: #1b1f3b;
  --card: #262b54;
  --ink: #f4f4ff;
  --muted: #a9add6;
  --accent: #ffd166;
  --p1: #4cc9f0;
  --p2: #f72585;
  --square: #343a6b;
}

* { box-sizing: border-box; }

[hidden] { display: none !important; }

html, body {
  margin: 0;
  padding: 0;
}

body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: radial-gradient(circle at top, #2a2f5e, var(--bg));
  color: var(--ink);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 18px;
  line-height: 1.4;
}

.card {
  width: 100%;
  max-width: 640px;
  background: var(--card);
  border-radius: 20px;
  padding: 24px;
  box-shadow: 0 20px 50px rgba(0, 0, 0, 0.45);
  text-align: center;
}

h1 {
  margin: 0 0 4px;
  font-size: 1.8rem;
  letter-spacing: 0.02em;
}

.subtitle {
  margin: 0 0 20px;
  color: var(--muted);
  font-size: 1rem;
}

.turn {
  margin-bottom: 16px;
  font-weight: 700;
  font-size: 1.15rem;
  min-height: 1.6em;
}

.track {
  display: grid;
  grid-template-columns: repeat(10, 1fr);
  gap: 4px;
  margin-bottom: 20px;
}

.square {
  position: relative;
  aspect-ratio: 1 / 1;
  background: var(--square);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.8rem;
  color: var(--muted);
  font-weight: 600;
}

.square .token {
  position: absolute;
  width: 38%;
  height: 38%;
  border-radius: 50%;
  border: 2px solid rgba(0, 0, 0, 0.3);
}

.square .token.p1 { background: var(--p1); left: 8%; bottom: 8%; }
.square .token.p2 { background: var(--p2); right: 8%; top: 8%; }

.square .num {
  font-size: 0.7rem;
  opacity: 0.7;
}

.players {
  display: flex;
  gap: 12px;
  justify-content: center;
  margin-bottom: 20px;
  flex-wrap: wrap;
}

.player {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 14px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  border: 2px solid transparent;
  transition: border-color 0.2s, background 0.2s;
}

.player.active {
  border-color: var(--accent);
  background: rgba(255, 209, 102, 0.12);
}

.dot {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  display: inline-block;
}

.dot.p1 { background: var(--p1); }
.dot.p2 { background: var(--p2); }

.pos {
  font-weight: 700;
  color: var(--accent);
}

.controls {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20px;
  flex-wrap: wrap;
}

.die {
  width: 64px;
  height: 64px;
  border-radius: 12px;
  background: var(--ink);
  color: var(--bg);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  font-weight: 800;
  box-shadow: inset 0 -4px 0 rgba(0, 0, 0, 0.15);
}

button {
  font: inherit;
  font-weight: 700;
  padding: 12px 24px;
  border: none;
  border-radius: 12px;
  background: var(--accent);
  color: #1b1f3b;
  cursor: pointer;
  transition: transform 0.08s, box-shadow 0.15s, filter 0.15s;
  box-shadow: 0 4px 0 #c9a13a;
}

button:hover { filter: brightness(1.05); }
button:active { transform: translateY(2px); box-shadow: 0 2px 0 #c9a13a; }
button:focus-visible { outline: 3px solid var(--p1); outline-offset: 3px; }
button:disabled { opacity: 0.5; cursor: not-allowed; box-shadow: none; }

.winner {
  margin-top: 20px;
  padding: 16px;
  border-radius: 14px;
  background: rgba(255, 209, 102, 0.14);
  border: 2px solid var(--accent);
}

.winner p {
  margin: 0 0 12px;
  font-size: 1.2rem;
  font-weight: 700;
}

@media (max-width: 420px) {
  body { padding: 10px; font-size: 16px; }
  .card { padding: 16px; border-radius: 16px; }
  h1 { font-size: 1.4rem; }
  .track { gap: 3px; }
  .square { font-size: 0.6rem; }
  .die { width: 54px; height: 54px; font-size: 1.6rem; }
  button { padding: 10px 18px; }
}

(function () {
  'use strict';

  var TOTAL = 20;
  var state = {
    positions: [1, 1],
    current: 0,
    over: false
  };

  var trackEl = document.getElementById('track');
  var turnLabel = document.getElementById('turnLabel');
  var dieEl = document.getElementById('die');
  var rollBtn = document.getElementById('rollBtn');
  var winnerBox = document.getElementById('winnerBox');
  var winnerText = document.getElementById('winnerText');
  var playAgainBtn = document.getElementById('playAgainBtn');
  var playerCards = [
    document.getElementById('player1Card'),
    document.getElementById('player2Card')
  ];
  var posEls = [
    document.getElementById('pos1'),
    document.getElementById('pos2')
  ];

  function buildTrack() {
    for (var i = 1; i <= TOTAL; i++) {
      var sq = document.createElement('div');
      sq.className = 'square';
      sq.setAttribute('role', 'listitem');
      sq.dataset.square = i;
      var num = document.createElement('span');
      num.className = 'num';
      num.textContent = i;
      sq.appendChild(num);
      var t1 = document.createElement('span');
      t1.className = 'token p1';
      t1.hidden = true;
      var t2 = document.createElement('span');
      t2.className = 'token p2';
      t2.hidden = true;
      sq.appendChild(t1);
      sq.appendChild(t2);
      trackEl.appendChild(sq);
    }
  }

  function renderTokens() {
    var squares = trackEl.querySelectorAll('.square');
    for (var i = 0; i < squares.length; i++) {
      var sq = squares[i];
      var n = Number(sq.dataset.square);
      sq.querySelector('.p1').hidden = state.positions[0] !== n;
      sq.querySelector('.p2').hidden = state.positions[1] !== n;
    }
  }

  function render() {
    renderTokens();
    posEls[0].textContent = state.positions[0];
    posEls[1].textContent = state.positions[1];
    playerCards[0].classList.toggle('active', !state.over && state.current === 0);
    playerCards[1].classList.toggle('active', !state.over && state.current === 1);
    turnLabel.textContent = state.over
      ? 'Game over'
      : 'Player ' + (state.current + 1) + "'s turn";
  }

  function rollDie() {
    return Math.floor(Math.random() * 6) + 1;
  }

  function handleRoll() {
    if (state.over) return;
    var roll = rollDie();
    dieEl.textContent = roll;
    dieEl.setAttribute('aria-label', 'Die showing ' + roll);

    var idx = state.current;
    var next = state.positions[idx] + roll;
    if (next > TOTAL) next = TOTAL;
    state.positions[idx] = next;

    if (next >= TOTAL) {
      state.over = true;
      winnerText.textContent = 'Player ' + (idx + 1) + ' wins!';
      winnerBox.hidden = false;
      rollBtn.disabled = true;
      render();
      playAgainBtn.focus();
      return;
    }

    state.current = idx === 0 ? 1 : 0;
    render();
  }

  function reset() {
    state.positions = [1, 1];
    state.current = 0;
    state.over = false;
    dieEl.textContent = '1';
    dieEl.setAttribute('aria-label', 'Die showing 1');
    winnerBox.hidden = true;
    rollBtn.disabled = false;
    render();
    rollBtn.focus();
  }

  buildTrack();
  render();

  rollBtn.addEventListener('click', handleRoll);
  playAgainBtn.addEventListener('click', reset);
})();
